--- a/src/lib/secrets.ts
+++ b/src/lib/secrets.ts
@@ -1,22 +1,36 @@
 import { PrismaClient } from '@prisma/client';
 import crypto from 'crypto';

 const prisma = new PrismaClient();
-const secretStore = new Map<string, string>();
+const CIPHER_ALGORITHM = 'aes-256-gcm';

-export function storeApiKey(userId: string, apiKey: string): void {
-  secretStore.set(userId, apiKey);
+function deriveKey(secret: string): Buffer {
+  return crypto.pbkdf2Sync(secret, 'salt', 100000, 32, 'sha256');
 }

-export function retrieveApiKey(userId: string): string | undefined {
-  return secretStore.get(userId);
+export async function storeApiKey(userId: string, apiKey: string): Promise<void> {
+  const key = deriveKey(process.env.ENCRYPTION_MASTER_KEY!);
+  const iv = crypto.randomBytes(12);
+  const cipher = crypto.createCipheriv(CIPHER_ALGORITHM, key, iv);
+  
+  let encrypted = cipher.update(apiKey, 'utf8', 'hex');
+  encrypted += cipher.final('hex');
+  const authTag = cipher.getAuthTag();
+  
+  await prisma.apiKey.upsert({
+    where: { userId },
+    update: { encryptedKey: encrypted, iv: iv.toString('hex'), authTag: authTag.toString('hex') },
+    create: { userId, encryptedKey: encrypted, iv: iv.toString('hex'), authTag: authTag.toString('hex') },
+  });
 }

-export function deleteApiKey(userId: string): boolean {
-  return secretStore.delete(userId);
+export async function retrieveApiKey(userId: string): Promise<string | null> {
+  const record = await prisma.apiKey.findUnique({ where: { userId } });
+  if (!record) return null;
+  
+  const key = deriveKey(process.env.ENCRYPTION_MASTER_KEY!);
+  const decipher = crypto.createDecipheriv(CIPHER_ALGORITHM, key, Buffer.from(record.iv, 'hex'));
+  decipher.setAuthTag(Buffer.from(record.authTag, 'hex'));
+  let decrypted = decipher.update(record.encryptedKey, 'hex', 'utf8');
+  decrypted += decipher.final('utf8');
+  return decrypted;
 }

