diff --git a/migrations/20261025_update_job_queue_locks.sql b/migrations/20261025_update_job_queue_locks.sql
new file mode 100644
index 0000000..2345678
--- /dev/null
+++ b/migrations/20261025_update_job_queue_locks.sql
@@ -0,0 +1,19 @@
+BEGIN;
+
+ALTER TABLE job_queue
+  DROP CONSTRAINT IF EXISTS job_queue_lock_version_key,
+  DROP COLUMN IF EXISTS lock_version,
+  ADD COLUMN processed_by VARCHAR(255),
+  ADD COLUMN locked_until TIMESTAMP;
+
+DROP FUNCTION IF EXISTS acquire_job_lock(bigint) CASCADE;
+
+CREATE FUNCTION acquire_job_lock(job_id bigint) RETURNS boolean AS $$
+BEGIN
+  UPDATE job_queue SET processed_by = current_user, locked_until = NOW() + INTERVAL '5 minutes'
+  WHERE id = job_id AND processed_by IS NULL;
+  RETURN FOUND;
+END;
+$$ LANGUAGE plpgsql;
+
+COMMIT;

