+  if (!EXPORT_ENABLED) {
+    return res.status(503).json({ error: 'Feature unavailable' });
+  }
+
+  const session = await getServerSession(req, res, authOptions);
+  if (!session) {
+    return res.status(401).json({ error: 'Unauthorized' });
+  }
+
+  if (req.method !== 'POST') {
+    return res.status(405).json({ error: 'Method not allowed' });
+  }
+
+  const { startDate, endDate, format } = req.body;
+  if (!startDate || !endDate) {
+    return res.status(400).json({ error: 'Missing date range' });
+  }
+
+  if (!['csv', 'json'].includes(format)) {
+    return res.status(400).json({ error: 'Invalid format' });
+  }
+
+  const data = await fetchAnalytics(session.user.id, startDate, endDate);
+  const exported = formatData(data, format);
+
+  res.status(200).json({ filename: `analytics-${Date.now()}.${format}`, data: exported });
+}
+
+async function fetchAnalytics(userId, start, end) { return []; }
