@@ -0,0 +1,30 @@
+import type { NextApiRequest, NextApiResponse } from 'next';
+import { getSession } from 'next-auth/react';
+import { prisma } from '@/lib/prisma';
+
+export default async function handler(
+  req: NextApiRequest,
+  res: NextApiResponse
+) {
+  const session = await getSession({ req });
+  
+  if (!session?.user?.id) {
+    return res.status(401).json({ error: 'Unauthorized' });
+  }
+
+  if (req.method === 'GET') {
+    const theme = await prisma.userTheme.findUnique({
+      where: { userId: session.user.id }
+    });
+    return res.status(200).json(theme || { mode: 'light' });
+  }
+
+  if (req.method === 'POST') {
+    const updated = await prisma.userTheme.upsert({
+      where: { userId: session.user.id },
+      update: { mode: req.body.mode },
+      create: { userId: session.user.id, mode: req.body.mode }
+    });
+    return res.status(200).json(updated);
+  }
+}

