+  }
+}
+
+resource "null_resource" "consolidate_customer_records" {
+  provisioner "local-exec" {
+    command = "psql -h ${var.db_host} -U ${var.db_user} -d ${var.database} -f ${path.module}/scripts/consolidate.sql"
+  }
+  depends_on = [null_resource.backup_customer_table]
+}
+
+resource "null_resource" "drop_legacy_schema" {
+  provisioner "local-exec" {
