+  }
+  depends_on = [null_resource.consolidate_customer_records]
+}
+
+resource "null_resource" "reindex_customers" {
+  provisioner "local-exec" {
+    command = "psql -h ${var.db_host} -U ${var.db_user} -d ${var.database} -c 'REINDEX TABLE customers;'"
+  }
