+import { useState, useEffect } from 'react';
+import { fetchUserData } from '../lib/api';
+
+interface User {
+  id: string;
+  name: string;
+  email: string;
+}
+
+export const useUserCache = () => {
+  const [user, setUser] = useState<User | null>(null);
+  const [loading, setLoading] = useState(true);
+
+  useEffect(() => {
+    fetchUserData().then(data => {
+      setUser(data);
+      setLoading(false);
+    });
+  }, []);
+
+  return { user, loading };
+};

