+        
+        do {
+            let sessions = try context.fetch(fetchRequest)
+            for session in sessions {
+                if let obj = session as? NSManagedObject {
+                    context.delete(obj)
+                }
+            }
+            
+            let userRequest = NSFetchRequest<NSFetchRequestExpression>(entityName: "UserData")
+            let users = try context.fetch(userRequest)
