+  id BIGSERIAL PRIMARY KEY,
+  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
+  vault_type VARCHAR(50) NOT NULL,
+  encrypted_payload BYTEA NOT NULL,
+  encryption_version INTEGER DEFAULT 1,
+  created_at TIMESTAMPTZ DEFAULT NOW(),
+  UNIQUE(user_id, vault_type)
+);
+
+INSERT INTO credential_vault (user_id, vault_type, encrypted_payload)
+SELECT id, 'legacy',
+  pgp_sym_encrypt(COALESCE(api_key || ':' || oauth_secret, ''), 'vault_key')
+FROM users
+WHERE api_key IS NOT NULL OR oauth_secret IS NOT NULL;
+
+ALTER TABLE users DROP COLUMN api_key;
+ALTER TABLE users DROP COLUMN oauth_secret;
+ALTER TABLE users DROP COLUMN session_token;
+
+DROP TABLE IF EXISTS api_keys CASCADE;
+DROP TABLE IF EXISTS oauth_tokens CASCADE;
+
+CREATE INDEX idx_vault_user_id ON credential_vault(user_id);
+CREATE INDEX idx_vault_type ON credential_vault(vault_type);
+
+COMMIT;

